const inicio = Date.now();
const fonte = $json.fonte;
const janela = $json.janela;
const modo = $json.modo;
const versaoApi = 'v1';

const locationId = String(fonte.externalId);
const metrics = ['WEBSITE_CLICKS', 'CALL_CLICKS', 'BUSINESS_DIRECTION_REQUESTS', 'BUSINESS_IMPRESSIONS_DESKTOP_MAPS', 'BUSINESS_IMPRESSIONS_MOBILE_SEARCH'];

function parseDate(dateStr) {
  const [year, month, day] = dateStr.split('-').map(Number);
  return { year, month, day };
}

const startDate = parseDate(janela.start);
const endDate = parseDate(janela.end);

const endpoint = `https://businessprofileperformance.googleapis.com/v1/locations/${locationId}:fetchMultiDailyMetricsTimeSeries`;
const queryParams = `dailyRange.start_date.year=${startDate.year}&dailyRange.start_date.month=${startDate.month}&dailyRange.start_date.day=${startDate.day}&dailyRange.end_date.year=${endDate.year}&dailyRange.end_date.month=${endDate.month}&dailyRange.end_date.day=${endDate.day}` + metrics.map(m => `&dailyMetrics=${m}`).join('');
const fullUrl = endpoint + '?' + queryParams;

function devolver(linhas, falhas, requests, bytes) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - inicio },
      falhas,
      requests,
      versaoApi,
    },
  }];
}

let resposta;
try {
  resposta = await this.helpers.httpRequestWithAuthentication.call(this, 'googleOAuth2Api', {
    method: 'GET',
    url: fullUrl,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
} catch (erro) {
  return devolver([], [{ causa: 'api_recusou', detalhe: `falha de rede: ${erro.message}` }], 1, 0);
}

if (resposta.statusCode === 401 || resposta.statusCode === 403) {
  const detalhe = resposta.body?.error?.message || `HTTP ${resposta.statusCode}`;
  return devolver([], [{ causa: 'reauth_pending', detalhe }], 1, 0);
}

if (resposta.statusCode < 200 || resposta.statusCode >= 300) {
  const detalhe = resposta.body?.error?.message || `HTTP ${resposta.statusCode}`;
  return devolver([], [{ causa: 'api_recusou', detalhe }], 1, 0);
}

const bytes = JSON.stringify(resposta.body).length;

const multiDailyMetricTimeSeries = resposta.body?.multiDailyMetricTimeSeries ?? [];
const linhas = [];

for (const serie of multiDailyMetricTimeSeries) {
  const dailyMetricTimeSeries = serie?.dailyMetricTimeSeries ?? [];
  for (const metricSerie of dailyMetricTimeSeries) {
    const dailyMetric = metricSerie?.dailyMetric ?? '';
    const datedValues = metricSerie?.timeSeries?.datedValues ?? [];
    for (const datedValue of datedValues) {
      const date = datedValue?.date ?? {};
      linhas.push({
        metricDate: `${String(date.year ?? 0).padStart(4, '0')}-${String(date.month ?? 0).padStart(2, '0')}-${String(date.day ?? 0).padStart(2, '0')}`,
        metric: dailyMetric,
        value: Number(datedValue?.value ?? 0),
      });
    }
  }
}

if (linhas.length === 0) {
  return devolver([], [{ causa: 'sem_dados_no_periodo', detalhe: null }], 1, bytes);
}

return devolver(linhas, [], 1, bytes);
